import os


class Client:
    """Stand-in for a provider SDK client: it refuses to be built without a key."""
    built = 0

    def __init__(self):
        if not os.environ.get("RAG_TOY_API_KEY"):
            raise RuntimeError("missing RAG_TOY_API_KEY")
        Client.built += 1

    def complete(self, prompt):
        return "answer to " + prompt


_client = None


def _get_client():
    global _client
    if _client is None:
        _client = Client()
    return _client


def complete(prompt):
    return _get_client().complete(prompt)
